/**
 * Transaction-scoped event outbox.
 *
 * Auto-generated by datrix-codegen-typescript. Do not edit manually.
 *
 * Domain events dispatched inside a `transaction(db) { ... }` unit of work are
 * buffered here and published once, *after* the transaction commits, instead of
 * once per row in a bulk loop. The buffer lives in an AsyncLocalStorage store so
 * concurrent requests never share or clobber each other's pending events.
 */
import { AsyncLocalStorage } from 'node:async_hooks';

export type DeferredPublish = () => Promise<void>;

const outboxStorage = new AsyncLocalStorage<DeferredPublish[]>();

// Maximum number of concurrent publish calls issued in a single flush wave.
// Limiting concurrency prevents flooding the broker producer's in-flight buffer
// when a bulk transaction(db) upsert buffers thousands of per-row lifecycle events.
const OUTBOX_FLUSH_BATCH_SIZE = 500;

/** True when a transaction-scoped event buffer is collecting events. */
export function outboxActive(): boolean {
  return outboxStorage.getStore() !== undefined;
}

/**
 * Queue a publish to run after the enclosing transaction commits.
 *
 * Guard calls with {@link outboxActive}; this throws if no buffer is active so
 * a misrouted defer fails loudly instead of silently dropping an event.
 */
export function deferEvent(send: DeferredPublish): void {
  const buffer = outboxStorage.getStore();
  if (buffer === undefined) {
    throw new Error(
      'deferEvent() called with no active event outbox. Guard publish calls ' +
        'with outboxActive() before deferring.',
    );
  }
  buffer.push(send);
}

/**
 * Drain *buffer* in bounded waves, logging failures without re-throwing.
 *
 * Publishes are issued in waves of at most {@link OUTBOX_FLUSH_BATCH_SIZE}
 * concurrent calls via `Promise.allSettled` so a broker timeout or transient
 * error in one wave does not abort the remaining events. All failures are
 * logged; this function always resolves normally so a post-commit outbox
 * failure never turns a durably-committed unit of work into an HTTP 5xx.
 */
async function flushBufferedEvents(buffer: DeferredPublish[]): Promise<void> {
  const total = buffer.length;
  let published = 0;
  let failed = 0;
  for (let start = 0; start < total; start += OUTBOX_FLUSH_BATCH_SIZE) {
    const wave = buffer.slice(start, start + OUTBOX_FLUSH_BATCH_SIZE);
    const results = await Promise.allSettled(wave.map((send) => send()));
    for (const result of results) {
      if (result.status === 'rejected') {
        failed += 1;
        // eslint-disable-next-line no-console
        console.error(`event_outbox_publish_failed error=${String(result.reason)}`);
      } else {
        published += 1;
      }
    }
  }
  if (failed > 0) {
    // eslint-disable-next-line no-console
    console.error(
      `event_outbox_flushed_with_failures published=${published} failed=${failed} total=${total}`,
    );
  } else {
    // eslint-disable-next-line no-console
    console.info(`event_outbox_flushed count=${published}`);
  }
}

/**
 * Buffer dispatched events and flush them once, after a clean exit.
 *
 * Re-entrant: a nested `bufferEvents()` joins the outermost buffer and leaves
 * flushing to it, so a `transaction` block nested inside another still yields
 * a single post-commit flush. On a thrown error inside *fn* nothing is
 * flushed -- the events belonged to a unit of work that rolled back.
 */
export async function bufferEvents<T>(fn: () => Promise<T>): Promise<T> {
  const existing = outboxStorage.getStore();
  if (existing !== undefined) {
    // Already buffering in an enclosing scope; it owns the flush.
    return fn();
  }
  const buffer: DeferredPublish[] = [];
  const result = await outboxStorage.run(buffer, fn);
  if (buffer.length > 0) {
    await flushBufferedEvents(buffer);
  }
  return result;
}
